import Event from "sap/ui/base/Event";                                                                                                                                                                                                                         
import Control from "sap/ui/core/Control";                                                                                                                                                                                                                     
import Controller from "sap/ui/core/mvc/Controller";                                                                                                                                                                                                           
import MessageBox from "sap/m/MessageBox";                                                                                                                                                                                                                     
import MessageToast from "sap/m/MessageToast";                                                                                                                                                                                                                 
import JSONModel from "sap/ui/model/json/JSONModel";                                                                                                                                                                                                           
import ODataModel from "sap/ui/model/odata/v4/ODataModel";                                                                                                                                                                                                     
import BarcodeScanner from "sap/ndc/BarcodeScanner";                                                                                                                                                                                                           
import Avatar from "sap/m/Avatar";                                                                                                                                                                                                                             
                                                                                                                                                                                                                                                               
type BarcodeScanResult = {                                                                                                                                                                                                                                     
    text: string;                                                                                                                                                                                                                                              
    cancelled: boolean;                                                                                                                                                                                                                                        
};                                                                                                                                                                                                                                                             
                                                                                                                                                                                                                                                               
type GrItem = {                                                                                                                                                                                                                                                
    ebeln: string;                                                                                                                                                                                                                                             
    ebelp: string;                                                                                                                                                                                                                                             
    werks: string;                                                                                                                                                                                                                                             
    lgort: string;                                                                                                                                                                                                                                             
    matnr: string;                                                                                                                                                                                                                                             
    quantity: number;                                                                                                                                                                                                                                          
    meins: string;                                                                                                                                                                                                                                             
    bwart: string;                                                                                                                                                                                                                                             
};                                                                                                                                                                                                                                                             
                                                                                                                                                                                                                                                               
type ScanData = GrItem & {                                                                                                                                                                                                                                     
    barcode: string;                                                                                                                                                                                                                                           
};                                                                                                                                                                                                                                                             
                                                                                                                                                                                                                                                               
type QueueData = {                                                                                                                                                                                                                                             
    items: GrItem[];                                                                                                                                                                                                                                           
    count: number;                                                                                                                                                                                                                                             
    hasItems: boolean;                                                                                                                                                                                                                                         
};                                                                                                                                                                                                                                                             
                                                                                                                                                                                                                                                               
export default class Z102_SCANNER extends Controller {                                                                                                                                                                                                         
    private static readonly CREATE_GR_ACTION =                                                                                                                                                                                                                 
        "/Gr/com.sap.gateway.srvd_a2x.zui_mm_gr_srv.v0001.CreateGr(...)";                                                                                                                                                                                      
                                                                                                                                                                                                                                                               
    public onInit(): void {                                                                                                                                                                                                                                    
        const logo = this.byId("logo") as Avatar | undefined;                                                                                                                                                                                                  
logo?.setSrc(sap.ui.require.toUrl("com/zmm/grscan/zmmgrscan/img/Mainlogo.png"));                                                                                                                                                                               
        this.getView()!.setModel(                                                                                                                                                                                                                              
            new JSONModel(this.createEmptyScanData()),                                                                                                                                                                                                         
            "scan"                                                                                                                                                                                                                                             
        );                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                               
        this.getView()!.setModel(                                                                                                                                                                                                                              
            new JSONModel({                                                                                                                                                                                                                                    
                items: [],                                                                                                                                                                                                                                     
                count: 0,                                                                                                                                                                                                                                      
                hasItems: false                                                                                                                                                                                                                                
            } as QueueData),                                                                                                                                                                                                                                   
            "queue"                                                                                                                                                                                                                                            
        );                                                                                                                                                                                                                                                     
    }                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                               
    public onStartScan(): void {                                                                                                                                                                                                                               
        BarcodeScanner.scan(                                                                                                                                                                                                                                   
            (oResult: BarcodeScanResult) => {                                                                                                                                                                                                                  
                if (!oResult.cancelled) {                                                                                                                                                                                                                      
                    this.applyBarcode(oResult.text);                                                                                                                                                                                                           
                }                                                                                                                                                                                                                                              
            },                                                                                                                                                                                                                                                 
            () => {                                                                                                                                                                                                                                            
                MessageBox.error("QR코드 또는 바코드를 읽지 못했습니다.");                                                                                                                                                                                                    
            }                                                                                                                                                                                                                                                  
        );                                                                                                                                                                                                                                                     
    }                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                               
    public onApplyManualBarcode(): void {                                                                                                                                                                                                                      
        this.applyBarcode(                                                                                                                                                                                                                                     
            String(this.getScanModel().getProperty("/barcode") || "")                                                                                                                                                                                          
        );                                                                                                                                                                                                                                                     
    }                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                               
    public onAddQueue(): void {                                                                                                                                                                                                                                
        const oScan = this.getScanModel().getData() as ScanData;                                                                                                                                                                                               
                                                                                                                                                                                                                                                               
        if (                                                                                                                                                                                                                                                   
            !oScan.ebeln ||                                                                                                                                                                                                                                    
            !oScan.ebelp ||                                                                                                                                                                                                                                    
            !oScan.werks ||                                                                                                                                                                                                                                    
            !oScan.lgort ||                                                                                                                                                                                                                                    
            !oScan.matnr ||                                                                                                                                                                                                                                    
            !oScan.meins                                                                                                                                                                                                                                       
        ) {                                                                                                                                                                                                                                                    
            MessageBox.warning("먼저 QR코드 또는 바코드를 읽어 주세요.");                                                                                                                                                                                                     
            return;                                                                                                                                                                                                                                            
        }                                                                                                                                                                                                                                                      
                                                                                                                                                                                                                                                               
        if (!Number.isFinite(Number(oScan.quantity)) || Number(oScan.quantity) <= 0) {                                                                                                                                                                         
            MessageBox.warning("입고 수량은 0보다 커야 합니다.");                                                                                                                                                                                                          
            return;                                                                                                                                                                                                                                            
        }                                                                                                                                                                                                                                                      
                                                                                                                                                                                                                                                               
        const aItems = [                                                                                                                                                                                                                                       
            ...(this.getQueueModel().getProperty("/items") as GrItem[]),                                                                                                                                                                                       
            {                                                                                                                                                                                                                                                  
                ebeln: oScan.ebeln,                                                                                                                                                                                                                            
                ebelp: oScan.ebelp,                                                                                                                                                                                                                            
                werks: oScan.werks,                                                                                                                                                                                                                            
                lgort: oScan.lgort,                                                                                                                                                                                                                            
                matnr: oScan.matnr,                                                                                                                                                                                                                            
                quantity: Number(oScan.quantity),                                                                                                                                                                                                              
                meins: oScan.meins,                                                                                                                                                                                                                            
                bwart: oScan.bwart                                                                                                                                                                                                                             
            }                                                                                                                                                                                                                                                  
        ];                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                               
        this.updateQueue(aItems);                                                                                                                                                                                                                              
        this.getScanModel().setData(this.createEmptyScanData());                                                                                                                                                                                               
                                                                                                                                                                                                                                                               
        MessageToast.show("입고 대기열에 추가했습니다.");                                                                                                                                                                                                                  
    }                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                               
    public onDeleteQueue(oEvent: Event): void {                                                                                                                                                                                                                
        const sPath = (oEvent.getSource() as Control)                                                                                                                                                                                                          
            .getBindingContext("queue")                                                                                                                                                                                                                        
            ?.getPath();                                                                                                                                                                                                                                       
                                                                                                                                                                                                                                                               
        const iIndex = Number(sPath?.split("/").pop());                                                                                                                                                                                                        
                                                                                                                                                                                                                                                               
        if (Number.isNaN(iIndex)) {                                                                                                                                                                                                                            
            return;                                                                                                                                                                                                                                            
        }                                                                                                                                                                                                                                                      
                                                                                                                                                                                                                                                               
        const aItems = [                                                                                                                                                                                                                                       
            ...(this.getQueueModel().getProperty("/items") as GrItem[])                                                                                                                                                                                        
        ];                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                               
        aItems.splice(iIndex, 1);                                                                                                                                                                                                                              
        this.updateQueue(aItems);                                                                                                                                                                                                                              
    }                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                               
    public async onConfirm(): Promise<void> {                                                                                                                                                                                                                  
        const aItems = this.getQueueModel().getProperty("/items") as GrItem[];                                                                                                                                                                                 
                                                                                                                                                                                                                                                               
        if (!aItems.length) {                                                                                                                                                                                                                                  
            MessageBox.warning("입고 대기열이 비어 있습니다.");                                                                                                                                                                                                            
            return;                                                                                                                                                                                                                                            
        }                                                                                                                                                                                                                                                      
                                                                                                                                                                                                                                                               
        const sRequestId = this.createRequestId();                                                                                                                                                                                                             
                                                                                                                                                                                                                                                               
        try {                                                                                                                                                                                                                                                  
            const oAction = this.getODataModel().bindContext(                                                                                                                                                                                                  
                Z102_SCANNER.CREATE_GR_ACTION                                                                                                                                                                                                                  
            );                                                                                                                                                                                                                                                 
                                                                                                                                                                                                                                                               
            oAction.setParameter("RequestId", sRequestId);                                                                                                                                                                                                     
                                                                                                                                                                                                                                                               
            oAction.setParameter(                                                                                                                                                                                                                              
                "_Item",                                                                                                                                                                                                                                       
                aItems.map((oItem, iIndex) => ({                                                                                                                                                                                                               
                    ScanNo: String(iIndex + 1).padStart(6, "0"),                                                                                                                                                                                               
                    Ebeln: oItem.ebeln,                                                                                                                                                                                                                        
                    Ebelp: oItem.ebelp,                                                                                                                                                                                                                        
                    Werks: oItem.werks,                                                                                                                                                                                                                        
                    Lgort: oItem.lgort,                                                                                                                                                                                                                        
                    Matnr: oItem.matnr,                                                                                                                                                                                                                        
                    MengeI: Number(oItem.quantity).toFixed(3), // 10 → "10.000"                                                                                                                                                                                
                    Meins: oItem.meins,                                                                                                                                                                                                                        
                    Bwart: oItem.bwart                                                                                                                                                                                                                         
                }))                                                                                                                                                                                                                                            
            );                                                                                                                                                                                                                                                 
                                                                                                                                                                                                                                                               
            await oAction.execute("$direct");                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                               
            this.updateQueue([]);                                                                                                                                                                                                                              
            this.getScanModel().setData(this.createEmptyScanData());                                                                                                                                                                                           
                                                                                                                                                                                                                                                               
            MessageToast.show("SAP 입고 처리가 완료되었습니다.");                                                                                                                                                                                                          
        } catch (_oError) {                                                                                                                                                                                                                                    
            MessageBox.error(                                                                                                                                                                                                                                  
                "이미 입고 처리된 QR코드입니다. 확인 부탁드립니다."                                                                                                                                                                                                                
            );                                                                                                                                                                                                                                                 
        }                                                                                                                                                                                                                                                      
    }                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                               
    private applyBarcode(sBarcode: string): void {                                                                                                                                                                                                             
        const sValue = sBarcode.trim();                                                                                                                                                                                                                        
        const aFields = sValue.split("|").map((sField) => sField.trim());                                                                                                                                                                                      
                                                                                                                                                                                                                                                               
        if (aFields.length !== 8 || aFields.some((sField) => !sField)) {                                                                                                                                                                                       
            MessageBox.warning(                                                                                                                                                                                                                                
                "QR 형식이 올바르지 않습니다.\nEBELN|EBELP|WERKS|LGORT|MATNR|MENGE|MEINS|BWART"                                                                                                                                                                           
            );                                                                                                                                                                                                                                                 
            return;                                                                                                                                                                                                                                            
        }                                                                                                                                                                                                                                                      
                                                                                                                                                                                                                                                               
        const [                                                                                                                                                                                                                                                
            ebeln = "",                                                                                                                                                                                                                                        
            ebelp = "",                                                                                                                                                                                                                                        
            werks = "",                                                                                                                                                                                                                                        
            lgort = "",                                                                                                                                                                                                                                        
            matnr = "",                                                                                                                                                                                                                                        
            quantityText = "",                                                                                                                                                                                                                                 
            meins = "",                                                                                                                                                                                                                                        
            bwart = ""                                                                                                                                                                                                                                         
        ] = aFields;                                                                                                                                                                                                                                           
                                                                                                                                                                                                                                                               
        const quantity = Number(quantityText);                                                                                                                                                                                                                 
                                                                                                                                                                                                                                                               
        if (!Number.isFinite(quantity) || quantity <= 0) {                                                                                                                                                                                                     
            MessageBox.warning("QR의 입고 수량이 올바르지 않습니다.");                                                                                                                                                                                                       
            return;                                                                                                                                                                                                                                            
        }                                                                                                                                                                                                                                                      
                                                                                                                                                                                                                                                               
        if (bwart !== "101") {                                                                                                                                                                                                                                 
            MessageBox.warning("입고 이동유형은 101만 가능합니다.");                                                                                                                                                                                                        
            return;                                                                                                                                                                                                                                            
        }                                                                                                                                                                                                                                                      
                                                                                                                                                                                                                                                               
        this.getScanModel().setData({                                                                                                                                                                                                                          
            barcode: sValue,                                                                                                                                                                                                                                   
            ebeln,                                                                                                                                                                                                                                             
            ebelp,                                                                                                                                                                                                                                             
            werks,                                                                                                                                                                                                                                             
            lgort,                                                                                                                                                                                                                                             
            matnr,                                                                                                                                                                                                                                             
            quantity,                                                                                                                                                                                                                                          
            meins,                                                                                                                                                                                                                                             
            bwart                                                                                                                                                                                                                                              
        } as ScanData);                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                               
        MessageToast.show("QR코드 정보를 읽었습니다.");                                                                                                                                                                                                                  
    }                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                               
    private createEmptyScanData(): ScanData {                                                                                                                                                                                                                  
        return {                                                                                                                                                                                                                                               
            barcode: "",                                                                                                                                                                                                                                       
            ebeln: "",                                                                                                                                                                                                                                         
            ebelp: "",                                                                                                                                                                                                                                         
            werks: "",                                                                                                                                                                                                                                         
            lgort: "",                                                                                                                                                                                                                                         
            matnr: "",                                                                                                                                                                                                                                         
            quantity: 1,                                                                                                                                                                                                                                       
            meins: "",                                                                                                                                                                                                                                         
            bwart: "101"                                                                                                                                                                                                                                       
        };                                                                                                                                                                                                                                                     
    }                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                               
    private updateQueue(aItems: GrItem[]): void {                                                                                                                                                                                                              
        this.getQueueModel().setData({                                                                                                                                                                                                                         
            items: aItems,                                                                                                                                                                                                                                     
            count: aItems.length,                                                                                                                                                                                                                              
            hasItems: aItems.length > 0                                                                                                                                                                                                                        
        } as QueueData);                                                                                                                                                                                                                                       
    }                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                               
    private createRequestId(): string {                                                                                                                                                                                                                        
        return `${Date.now().toString(16)}${Math.random()                                                                                                                                                                                                      
            .toString(16)                                                                                                                                                                                                                                      
            .slice(2)}`                                                                                                                                                                                                                                        
            .padEnd(32, "0")                                                                                                                                                                                                                                   
            .slice(0, 32)                                                                                                                                                                                                                                      
            .toUpperCase();                                                                                                                                                                                                                                    
    }                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                               
    private getODataModel(): ODataModel {                                                                                                                                                                                                                      
        const oModel = this.getOwnerComponent()?.getModel();                                                                                                                                                                                                   
                                                                                                                                                                                                                                                               
        if (!oModel) {                                                                                                                                                                                                                                         
            throw new Error("기본 OData 모델을 찾을 수 없습니다.");                                                                                                                                                                                                        
        }                                                                                                                                                                                                                                                      
                                                                                                                                                                                                                                                               
        return oModel as ODataModel;                                                                                                                                                                                                                           
    }                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                               
    private getScanModel(): JSONModel {                                                                                                                                                                                                                        
        return this.getView()!.getModel("scan") as JSONModel;                                                                                                                                                                                                  
    }                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                               
    private getQueueModel(): JSONModel {                                                                                                                                                                                                                       
        return this.getView()!.getModel("queue") as JSONModel;                                                                                                                                                                                                 
    }                                                                                                                                                                                                                                                          
}                                                                                                                                                                                                                                                              